"""Camera-guided controller for the one ongoing hardware-service episode.
Only Robot.spec(), get_obs(), submit(), status() are used.
Panda forward kinematics are computed locally from the public arm geometry.
All executed actions are recorded in actions.jsonl and can be replayed.
"""
import argparse,json
from pathlib import Path
import numpy as np
from scipy.spatial.transform import Rotation as Rot
from scipy.optimize import least_squares
from rcb_client import Robot

OUT=Path('/app/output'); OUT.mkdir(exist_ok=True)
LIMITS=np.array([[-2.8973,2.8973],[-1.7628,1.7628],[-2.8973,2.8973],[-3.0718,-.0698],[-2.8973,2.8973],[-.0175,3.7525],[-2.8973,2.8973]])

def raw_fk(q):
    T=np.eye(4);T[:3,:3]=Rot.from_euler('z',np.pi/2).as_matrix();T[:3,3]=[0,-.4,.78]
    for a,d,al,qi in zip([0,0,0,.0825,-.0825,0,.088],[.333,0,.316,0,.384,0,0],[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2],q):
        U=np.eye(4);U[:3,:3]=Rot.from_euler('x',al).as_matrix();U[0,3]=a
        V=np.eye(4);V[:3,:3]=Rot.from_euler('z',qi).as_matrix();V[2,3]=d;T=T@U@V
    U=np.eye(4);U[2,3]=.2;U[:3,:3]=Rot.from_euler('z',-np.pi/4).as_matrix()
    return T@U

def calibration(n):
    T=np.eye(4);T[:3,3]=n[16:19];T[:3,:3]=Rot.from_quat(n[19:23],scalar_first=True).as_matrix()
    return T@np.linalg.inv(raw_fk(n[:7]))

class Controller:
    def __init__(self):
        self.r=Robot();self.spec=self.r.spec()
        if not (OUT/'calibration.npy').exists():
            o=self.r.get_obs(video='none');np.save(OUT/'calibration.npy',calibration(o.meta['proprio']['now']))
        self.C=np.load(OUT/'calibration.npy')
    def obs(self,name='obs',depth=True):
        o=self.r.get_obs(video='none',include_depth=depth);o.save(str(OUT/name));return o
    def fk(self,q):return self.C@raw_fk(q)
    def ik(self,p,R,q):
        q=np.asarray(q)
        def residual(v):
            t=self.fk(v)
            return np.r_[10*(t[:3,3]-p),Rot.from_matrix(R@t[:3,:3].T).as_rotvec(),.008*(v-q)]
        sol=least_squares(residual,np.clip(q,LIMITS[:,0]+.001,LIMITS[:,1]-.001),bounds=(LIMITS[:,0]+.001,LIMITS[:,1]-.001),xtol=1e-10,ftol=1e-10,gtol=1e-10,max_nfev=350)
        T=self.fk(sol.x);pe=np.linalg.norm(T[:3,3]-p);re=np.linalg.norm(Rot.from_matrix(R@T[:3,:3].T).as_rotvec())
        if pe>.005 or re>.025:raise ValueError(f'Unreachable pose: position error {pe}, rotation {re}; q={sol.x}')
        return sol.x
    def execute(self,A,note,cameras=None):
        A=np.asarray(A);assert A.shape[1]==9
        assert np.all(A[:,:7]>=LIMITS[:,0]) and np.all(A[:,:7]<=LIMITS[:,1])
        with (OUT/'actions.jsonl').open('a') as f:f.write(json.dumps({'note':note,'dt':.1,'actions':A.tolist()})+'\n')
        o=self.r.submit('joint_position',A,dt=.1,interpolate='linear',cameras=cameras or ['forward','left','right','wrist'],video='none',include_depth=True,note=note)
        o.save(str(OUT/note)); print(json.dumps({'note':note,'done':o.meta['done'],'reason':o.meta['reason'],'steps':o.meta['control_steps'],'now':o.meta['proprio']['now'][:23]}),flush=True)
        return o
    def move(self,p,R=None,fingers=.04,seconds=3.,note='move'):
        n=self.obs('latest',False).meta['proprio']['now'];q=np.array(n[:7]);T=self.fk(q)
        if R is None:R=T[:3,:3]
        nr=max(2,int(round(seconds/.1))); actions=[]
        rot=Rot.from_matrix(R@T[:3,:3].T).as_rotvec()
        for u in np.linspace(0,1,nr+1)[1:]:
            v=u*u*(3-2*u);p1=(1-v)*T[:3,3]+v*np.array(p);R1=Rot.from_rotvec(v*rot).as_matrix()@T[:3,:3]
            q=self.ik(p1,R1,q);actions.append(np.r_[q,[fingers,fingers]])
        # Settle for half a second at the final target.
        actions.extend([actions[-1]]*5)
        return self.execute(actions,note)
    def grip(self,width=.0,seconds=2.,note='grip'):
        n=self.obs('latest',False).meta['proprio']['now'];A=np.tile(np.r_[n[23:30],[width,width]],(int(seconds/.1),1));return self.execute(A,note)

# Horizontal approach: local z points forward, finger closure along world x.
FORWARD=np.array([[0,1,0],[0,0,1],[1,0,0]],dtype=float)
if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('command',choices=['observe','move','grip','replay']);ap.add_argument('--position',nargs=3,type=float);ap.add_argument('--orientation',choices=['forward','keep'],default='keep');ap.add_argument('--width',type=float,default=.04);ap.add_argument('--seconds',type=float,default=3.);ap.add_argument('--name',default='obs');a=ap.parse_args();c=Controller()
    if a.command=='observe':
        o=c.obs(a.name);print(json.dumps(o.meta));print(c.r.status())
    elif a.command=='move':c.move(a.position,FORWARD if a.orientation=='forward' else None,a.width,a.seconds,a.name)
    elif a.command=='grip':c.grip(a.width,a.seconds,a.name)
    else:
        for line in (OUT/'actions.jsonl').read_text().splitlines():
            rec=json.loads(line);o=c.r.submit('joint_position',rec['actions'],dt=rec['dt'],interpolate='linear',video='none',cameras=['forward'],note=rec['note'])
            if o.done:break
